"use strict";(self.webpackChunkmy_site=self.webpackChunkmy_site||[]).push([["5568"],{724(e){e.exports=JSON.parse('{"tag":{"label":"Differential Geometry","permalink":"/docs/tags/differential-geometry","allTagsPath":"/docs/tags","count":4,"items":[{"id":"Differential Geometry and Fibre Bundle/topology","title":"Basic Topology for Differential Geometry","description":"It\'s assumed that you have basic knowledge of sets, including the definition, Cartesian product, etc.","permalink":"/docs/Differential Geometry and Fibre Bundle/topology"},{"id":"Differential Geometry and Fibre Bundle/change-of-basis","title":"Change of Basis","description":"Finally, we now have enough basic machinery to answer a very fundamental question: why are the components of a vector written with upper indices, while those of a covector use lower indices, and why is it the opposite for basis vectors? This entire \u201Ctragedy\u201D ultimately comes from physicists naming things according to the shape of basis transformations.","permalink":"/docs/Differential Geometry and Fibre Bundle/change-of-basis"},{"id":"Differential Geometry and Fibre Bundle/tensors","title":"Introduction to Tensors","description":"In matrix language, vectors are represented as column vectors, while covectors (another name for dual vectors) are represented as row vectors. Then what exactly is a matrix? We will use this question as motivation to introduce the definition of tensors.","permalink":"/docs/Differential Geometry and Fibre Bundle/tensors"},{"id":"Differential Geometry and Fibre Bundle/linear-algebra","title":"Linear Algebra for Differential Geometry","description":"We assume the reader already has some basic familiarity with linear algebra, such as the definitions of vector spaces and bases.","permalink":"/docs/Differential Geometry and Fibre Bundle/linear-algebra"}],"unlisted":false}}')}}]);